var tests = new List<(string Name, Action Body)>();
void Test(string name, Action action) => tests.Add((name, action));
void Assert(bool condition, string message = "Assertion failed") { if (!condition) throw new Exception(message); }
void Equal<T>(T expected, T actual) { if (!EqualityComparer<T>.Default.Equals(expected, actual)) throw new Exception($"Expected {expected}; got {actual}"); }
void Near(double expected, double actual, double epsilon = .00001) => Assert(Math.Abs(expected - actual) <= epsilon, $"Expected approximately {expected}; got {actual}");
void Throws<T>(Action action) where T : Exception { try { action(); } catch (T) { return; } throw new Exception("Expected " + typeof(T).Name); }
TagDefinition Tag(string path = "[default]Value", double value = 10, bool writable = true) => new() { Path = path, InitialValue = Scalar.From(value), Minimum = 0, Maximum = 100, Writable = writable };
var expr = new ExpressionEngine();

Test("scalar finite and invariant conversions", () => { Near(2.5, Scalar.Parse("2.5", ScalarKind.Number).AsNumber()); Equal("true", Scalar.From(true).ToString()); Equal(1d, Scalar.From(true).AsNumber()); Throws<ArgumentOutOfRangeException>(() => Scalar.From(double.NaN)); Throws<ArgumentOutOfRangeException>(() => Scalar.From(double.PositiveInfinity)); Assert(!Scalar.Null.AsBoolean()); });
Test("strict provider-qualified tag paths", () => { foreach (var path in new[] { "[default]X", "[p]Folder/Tag", "[remote]Motor 1/Speed" }) Assert(TagPaths.IsValid(path)); foreach (var path in new[] { "", "X", "[]X", "[p]", "[p]/X", "[p]X/", "[p]../X", "[p]X//Y", "[p]X\nY", "[p]X[q]" }) Assert(!TagPaths.IsValid(path), path); });
Test("numeric operator precedence", () => { Near(14, expr.Evaluate("2 + 3 * 4").AsNumber()); Near(20, expr.Evaluate("(2 + 3) * 4").AsNumber()); Near(512, expr.Evaluate("2 ^ 3 ^ 2").AsNumber()); Near(.012, expr.Evaluate("1.2e-2").AsNumber()); Near(1, expr.Evaluate("7 % 3").AsNumber()); });
Test("lazy boolean and conditional evaluation", () => { Assert(!expr.Evaluate("false && (1 / 0 > 2)").AsBoolean()); Assert(expr.Evaluate("true || missing").AsBoolean()); Near(3, expr.Evaluate("if(true, 3, 1 / 0)").AsNumber()); Near(8, expr.Evaluate("false ? 1 / 0 : 8").AsNumber()); Near(7, expr.Evaluate("coalesce(null, 7, missing)").AsNumber()); });
Test("expression strings and functions", () => { Equal("Pump 4", expr.Evaluate("'Pump ' + 4").ToString()); Equal("PUMP", expr.Evaluate("upper('pump')").ToString()); Equal("abc", expr.Evaluate("substring('abcdef', 0, 3)").ToString()); Near(10, expr.Evaluate("clamp(25, 0, 10)").AsNumber()); Near(5, expr.Evaluate("max(1,5,3)").AsNumber()); Equal("3.14", expr.Evaluate("numberFormat(3.14159, '0.00')").ToString()); Assert(expr.Evaluate("contains('ABC', 'B') and not false").AsBoolean()); });
Test("reference dependencies are explicit and deduplicated", () => { var compiled = expr.Compile("{[default]X} + {[default]X} + value"); Equal(2, compiled.Dependencies.Count); Near(7, compiled.Evaluate(p => Scalar.From(p == "value" ? 3 : 2)).AsNumber()); Assert(ReferenceEquals(compiled, expr.Compile("{[default]X} + {[default]X} + value"))); });
Test("invalid expressions and arbitrary code rejected", () => { foreach (var code in new[] { "1/0", "sqrt(-1)", "foo(1)", "1;2", "System.IO.File.ReadAllText('x')", "1 +", "(1", "'abc", "{x", "if(1,2)", "1e999", "2 3", "min()" }) Throws<ExpressionException>(() => expr.Evaluate(code)); Throws<ExpressionException>(() => expr.Compile(new string('(', 80) + "1" + new string(')', 80))); Throws<ExpressionException>(() => expr.Compile(new string('x', 17000))); });
Test("tag revisions and optimistic writes", () => { var tags = new TagStore([Tag()]); var old = tags.Read("[default]Value"); var first = tags.Write("[default]Value", Scalar.From(20), "tester", old.Revision); Assert(first.Success); Assert(first.Current.Revision > old.Revision); Equal(WriteStatus.RevisionConflict, tags.Write("[default]Value", Scalar.From(30), "tester", old.Revision).Status); Near(20, tags.Read("[default]Value").Value.Number); Equal(2, tags.Audit.Snapshot().Length); });
Test("tag writable type and range enforcement", () => { var tags = new TagStore([Tag(), Tag("[default]ReadOnly", writable: false)]); Equal(WriteStatus.ReadOnly, tags.Write("[default]ReadOnly", Scalar.From(30), "test").Status); Equal(WriteStatus.BadType, tags.Write("[default]Value", Scalar.From("text"), "test").Status); Equal(WriteStatus.OutOfRange, tags.Write("[default]Value", Scalar.From(101), "test").Status); Equal(Quality.BadNotFound, tags.Read("[default]Missing").Quality); tags.WritesEnabled = false; Equal(WriteStatus.Disabled, tags.Write("[default]Value", Scalar.From(20), "test").Status); Assert(tags.Publish("[default]ReadOnly", Scalar.From(40)).Success); });
Test("tag definitions and snapshots are detached", () => { var definition = Tag(); var tags = new TagStore([definition]); definition.Writable = false; tags.Browse()[0].Writable = false; Assert(tags.Write("[default]Value", Scalar.From(11), "test").Success); var snapshot = tags.Snapshot(); snapshot.Clear(); Equal(1, tags.Browse().Count); });
Test("subscriptions dispose and isolate exceptions", () => { var tags = new TagStore([Tag()]); var called = 0; using var bad = tags.Subscribe(_ => throw new Exception("subscriber error")); var good = tags.Subscribe(_ => called++); tags.Publish("[default]Value", Scalar.From(11)); Equal(1, called); good.Dispose(); good.Dispose(); tags.Publish("[default]Value", Scalar.From(12)); Equal(1, called); });
Test("historian ring eviction and UTC ordering", () => { var clock = new TestClock(); var tags = new TagStore([Tag()], clock: clock); using var history = new Historian(tags, 4); for (var i = 0; i < 10; i++) { clock.Advance(1); tags.Publish("[default]Value", Scalar.From(i)); } var values = history.Query("[default]Value"); Equal(4, values.Length); Near(6, values[0].Value.Number); Near(9, values[^1].Value.Number); Assert(!history.Append("[default]Value", values[0])); Equal(0, history.Query("[default]Missing").Length); });
Test("history deadband does not hide quality changes", () => { var clock = new TestClock(); var tag = Tag(); tag.HistoryDeadband = 5; var tags = new TagStore([tag], clock: clock); using var history = new Historian(tags); clock.Advance(1); tags.Publish(tag.Path, Scalar.From(12)); Equal(1, history.Query(tag.Path).Length); clock.Advance(1); tags.Publish(tag.Path, Scalar.From(12), Quality.Stale); Equal(2, history.Query(tag.Path).Length); });
Test("history aggregation and missing buckets", () => { var clock = new TestClock(); var tags = new TagStore([Tag(value: 0)], clock: clock); using var history = new Historian(tags); var start = clock.GetUtcNow(); for (var i = 1; i <= 4; i++) { clock.Advance(1); tags.Publish("[default]Value", Scalar.From(i * 10)); } var bucket = history.Aggregate("[default]Value", start, start.AddSeconds(5), 1, AggregateKind.Average).Single(); Near(20, bucket.Value.Number); Equal(5, bucket.Count); Equal(Quality.BadNotFound, history.Aggregate("[default]Value", start.AddHours(1), start.AddHours(2), 2, AggregateKind.Average)[0].Quality); });
Test("history decimation preserves spikes", () => { var now = DateTimeOffset.UtcNow; var values = Enumerable.Range(0, 1000).Select(i => QualifiedValue.Good(Scalar.From(i == 537 ? 100 : 1), now.AddSeconds(i), i)).ToArray(); var reduced = Historian.Decimate(values, 20); Assert(reduced.Length <= 42); Assert(reduced.Any(x => x.Value.Number == 100)); Equal(values[0], reduced[0]); Equal(values[^1], reduced[^1]); });
Test("CSV export protects formula-like strings", () => { var tag = new TagDefinition { Path = "[default]Text", DataType = ScalarKind.String, InitialValue = Scalar.From("=1+1") }; using var history = new Historian(new TagStore([tag])); Assert(history.ExportCsv(tag.Path).Contains("\"'=1+1\"")); });
Test("alarm four state lifecycle and audit", () => { var clock = new TestClock(); var tags = new TagStore([Tag()], clock: clock); using var alarms = new AlarmEngine(tags, [new() { Id = "high", Name = "High", TagPath = "[default]Value", Setpoint = 80, Deadband = 2 }], tags.Audit, clock); Equal(0, alarms.Status().Length); tags.Publish("[default]Value", Scalar.From(85)); var alarm = alarms.Status().Single(); Assert(alarm.Active && !alarm.Acknowledged); Assert(alarms.Acknowledge(alarm.EventId, "operator")); Assert(!alarms.Acknowledge(alarm.EventId, "operator")); tags.Publish("[default]Value", Scalar.From(79)); Assert(alarms.Status().Single().Active); tags.Publish("[default]Value", Scalar.From(78)); Equal(0, alarms.Status().Length); Equal(3, alarms.Journal().Length); Equal(1, tags.Audit.Snapshot().Length); });
Test("cleared unacknowledged alarms remain visible", () => { var tags = new TagStore([Tag()]); using var alarms = new AlarmEngine(tags, [new() { TagPath = "[default]Value", Setpoint = 80 }]); tags.Publish("[default]Value", Scalar.From(90)); tags.Publish("[default]Value", Scalar.From(10)); Assert(!alarms.Status().Single().Active); Assert(!alarms.Status().Single().Acknowledged); });
Test("alarm activation and clear delays", () => { var clock = new TestClock(); var tags = new TagStore([Tag()], clock: clock); using var alarms = new AlarmEngine(tags, [new() { TagPath = "[default]Value", Setpoint = 80, ActiveDelaySeconds = 2, ClearDelaySeconds = 3 }], clock: clock); tags.Publish("[default]Value", Scalar.From(90)); Equal(0, alarms.Status().Length); clock.Advance(1); alarms.Evaluate(); Equal(0, alarms.Status().Length); clock.Advance(1); alarms.Evaluate(); Assert(alarms.Status().Single().Active); tags.Publish("[default]Value", Scalar.From(10)); clock.Advance(2); alarms.Evaluate(); Assert(alarms.Status().Single().Active); clock.Advance(1); alarms.Evaluate(); Assert(!alarms.Status().Single().Active); });
Test("bad quality cannot silently clear alarms", () => { var tags = new TagStore([Tag(value: 90)]); using var alarms = new AlarmEngine(tags, [new() { TagPath = "[default]Value", Setpoint = 80 }]); tags.Publish("[default]Value", Scalar.From(10), Quality.Stale); Assert(alarms.Status().Single().Active); });
Test("shelving expires and requires actor", () => { var clock = new TestClock(); var tags = new TagStore([Tag(value: 90)], clock: clock); using var alarms = new AlarmEngine(tags, [new() { TagPath = "[default]Value", Setpoint = 80 }], clock: clock); var id = alarms.Status().Single().EventId; Assert(alarms.Shelve(id, TimeSpan.FromSeconds(5), "operator")); Equal(0, alarms.Status(false).Length); clock.Advance(5); alarms.Evaluate(); Equal(1, alarms.Status(false).Length); Throws<ArgumentException>(() => alarms.Acknowledge(id, "")); Throws<ArgumentOutOfRangeException>(() => alarms.Shelve(id, TimeSpan.FromDays(2), "operator")); });
Test("demo project JSON is lossless and validated", () => { var project = DemoProject.Create(); Equal(0, ProjectCodec.Validate(project).Count); var copy = ProjectCodec.Deserialize(ProjectCodec.Serialize(project)); Equal(project.Views.Count, copy.Views.Count); Equal(project.Tags.Count, copy.Tags.Count); Equal(ProjectCodec.Serialize(project), ProjectCodec.Serialize(copy)); });
Test("invalid project transactions are rejected", () => { var project = DemoProject.Create(); project.SchemaVersion = 99; Throws<FormatException>(() => ProjectCodec.Deserialize(ProjectCodec.Serialize(project))); project = DemoProject.Create(); project.Views[0].Root.Children[0].Width = -1; Assert(ProjectCodec.Validate(project).Count > 0); project = DemoProject.Create(); project.Views[1].Root.Id = project.Views[0].Root.Id; Assert(ProjectCodec.Validate(project).Count > 0); });
Test("view instance parameters and indirect tag bindings", () => { using var runtime = new ProjectRuntime(DemoProject.Create()); var a = runtime.CreateView("EquipmentDetail", new Dictionary<string, Scalar> { ["equipment"] = Scalar.From("Tank01") }); var b = runtime.CreateView("EquipmentDetail", new Dictionary<string, Scalar> { ["equipment"] = Scalar.From("Tank02") }); a.Evaluate(); b.Evaluate(); Near(68.4, a.Read(a.View.Root.Children[1], "value").Value.Number); Near(43.8, b.Read(b.View.Root.Children[1], "value").Value.Number); Equal("Equipment / Tank01", a.Read(a.View.Root.Children[0], "text").Value.ToString()); });
Test("tag path parameters cannot traverse providers", () => { using var runtime = new ProjectRuntime(DemoProject.Create()); var view = runtime.CreateView("EquipmentDetail", new Dictionary<string, Scalar> { ["equipment"] = Scalar.From("../Tank01") }); Throws<ExpressionException>(() => view.ResolveTagPath("[default]Plant/{equipment}/Level")); });
Test("bidirectional writes are explicit", () => { using var runtime = new ProjectRuntime(DemoProject.Create()); var view = runtime.CreateView("Overview"); view.Evaluate(); var input = view.View.Root.Children.Single(n => n.Name == "LevelSetpoint"); Assert(view.Write(input, "value", Scalar.From(81), "operator").Success); Near(81, runtime.Tags.Read("[default]Plant/Tank01/Setpoint").Value.Number); var tank = view.View.Root.Children.Single(n => n.Name == "Tank01"); Equal(WriteStatus.ReadOnly, view.Write(tank, "value", Scalar.From(50), "operator").Status); });
Test("binding transforms and cyclic graphs", () => { using var runtime = new ProjectRuntime(DemoProject.Create()); var view = runtime.CreateView("Overview"); var tank = view.View.Root.Children.Single(n => n.Name == "Tank01"); tank.Bindings["value"].Transforms.Add(new() { Kind = TransformKind.Scale, InputMin = 0, InputMax = 100, OutputMin = 0, OutputMax = 1 }); view.Evaluate(); Near(.684, view.Read(tank, "value").Value.Number); tank.Bindings["value"] = new() { Kind = BindingKind.Expression, Source = "{this.props.value} + 1" }; view.Evaluate(); Equal(Quality.BadExpression, view.Read(tank, "value").Quality); Assert(view.Diagnostics.Count > 0); });
Test("runtime navigation history and declarative actions", () => { using var runtime = new ProjectRuntime(DemoProject.Create()); var session = new RuntimeSession(runtime); Assert(session.Navigate("/trends")); Equal("/trends", session.CurrentPath); Assert(session.Back()); Equal("/", session.CurrentPath); Assert(!session.Navigate("/missing")); var stop = runtime.Project.Views[0].Root.Children.Single(n => n.Name == "StopPump"); session.Dispatch(stop, "onAction"); Assert(!runtime.Tags.Read("[default]Plant/Pump/Enabled").Value.Boolean); });
Test("designer undo redo restores complete edits", () => { var doc = new DesignerDocument(DemoProject.Create()); var id = doc.Project.Views[0].Root.Children.Single(n => n.Name == "Tank01").Id; doc.Select(id); var x = doc.Find(id)!.X; doc.Move(16, 8, 8); Near(x + 16, doc.Find(id)!.X); Assert(doc.IsDirty); Assert(doc.Undo()); Near(x, doc.Find(id)!.X); Assert(!doc.IsDirty); Assert(doc.Redo()); Near(x + 16, doc.Find(id)!.X); doc.MarkSaved(); Assert(!doc.IsDirty); });
Test("designer failed edits roll back atomically", () => { var doc = new DesignerDocument(DemoProject.Create()); var before = ProjectCodec.Serialize(doc.Project); Throws<InvalidOperationException>(() => doc.Execute("invalid", p => p.Views[0].Root.Width = -20)); Equal(before, ProjectCodec.Serialize(doc.Project)); Assert(!doc.CanUndo); });
Test("designer clipboard remaps IDs", () => { var doc = new DesignerDocument(DemoProject.Create()); var root = doc.Project.Views[0].Root; var first = root.Children.Single(n => n.Name == "Tank01"); doc.Select(first.Id); var count = root.Children.Count; doc.Paste(doc.CopySelection(), root.Id); Equal(count + 1, doc.Project.Views[0].Root.Children.Count); Assert(doc.Selection.Single() != first.Id); Equal(0, ProjectCodec.Validate(doc.Project).Count); doc.Delete(); Equal(count, doc.Project.Views[0].Root.Children.Count); });
Test("designer locked controls do not move", () => { var doc = new DesignerDocument(DemoProject.Create()); var node = doc.Project.Views[0].Root.Children[0]; node.Locked = true; doc.Select(node.Id); var x = node.X; doc.Move(25, 30); Near(x, doc.Find(node.Id)!.X); });
Test("coordinate layout and hit testing", () => { var root = new ComponentNode { Type = "Container", Width = 500, Height = 300 }; var child = ComponentCatalog.Create("Label", 10, 20); root.Children.Add(child); var slots = LayoutEngine.Flatten(root, 500, 300); Equal(new RectD(10, 20, 160, 36), slots[0].Bounds); Equal(child.Id, LayoutEngine.HitTest(slots, 30, 30)!.Node.Id); Assert(LayoutEngine.HitTest(slots, 490, 290) is null); });
Test("weighted flex distributes available space", () => { var root = new ComponentNode { Type = "Container", Layout = LayoutKind.FlexRow }; root.Props["gap"] = Scalar.From(10); var a = ComponentCatalog.Create("Label"); var b = ComponentCatalog.Create("Label"); a.Width = b.Width = 100; a.Props["grow"] = Scalar.From(1); b.Props["grow"] = Scalar.From(3); root.Children.AddRange([a, b]); var slots = LayoutEngine.Arrange(root, 610, 80); Near(200, slots[0].Bounds.Width); Near(400, slots[1].Bounds.Width); Near(210, slots[1].Bounds.X); });
Test("responsive columns and breakpoint stacking", () => { var root = new ComponentNode { Type = "Container", Layout = LayoutKind.Breakpoint }; root.Children.AddRange([ComponentCatalog.Create("Label"), ComponentCatalog.Create("Label")]); var narrow = LayoutEngine.Arrange(root, 300, 200); Assert(narrow[1].Bounds.Y > 0); var wide = LayoutEngine.Arrange(root, 800, 200); Assert(wide[1].Bounds.X > 0); root.Layout = LayoutKind.Tab; root.Props["activeTab"] = Scalar.From(1); var tabs = LayoutEngine.Arrange(root, 500, 200); Assert(!tabs[0].Visible && tabs[1].Visible); });
Test("file repository compares revisions and round-trips", () => { var path = Path.Combine(Path.GetTempPath(), "scadaspace-test-" + Guid.NewGuid() + ".json"); try { using var repo = new FileProjectRepository(path); var project = DemoProject.Create(); Equal(1L, repo.SaveAsync(project, 0).GetAwaiter().GetResult()); Equal(project.Name, repo.LoadAsync().GetAwaiter().GetResult()!.Name); Throws<ProjectConflictException>(() => repo.SaveAsync(project, 0).GetAwaiter().GetResult()); Equal(2L, repo.SaveAsync(project, 1).GetAwaiter().GetResult()); } finally { File.Delete(path); } });
Test("simulator operates only declared in-memory tags", () => { using var runtime = new ProjectRuntime(DemoProject.Create()); var sim = new PlantSimulator(runtime.Tags); sim.Advance(TimeSpan.FromSeconds(1)); Assert(runtime.Tags.Read("[default]Plant/Tank01/Level").Value.Number > 68.4); runtime.Tags.Write("[default]Plant/Pump/Enabled", Scalar.From(false), "test"); sim.Advance(TimeSpan.FromSeconds(1)); Near(0, runtime.Tags.Read("[default]Plant/Pump/Flow").Value.Number); Equal(8, runtime.Tags.Browse().Count); });

var results = new List<object>(); var failures = 0; var suite = new XElement("testsuite", new XAttribute("name", "ScadaSpace"));
foreach (var (name, body) in tests)
{
    var start = System.Diagnostics.Stopwatch.StartNew();
    var entry = new XElement("testcase", new XAttribute("name", name));
    try { body(); Console.WriteLine("PASS " + name); results.Add(new { name, passed = true }); }
    catch (Exception ex) { failures++; Console.WriteLine("FAIL " + name + "\n" + ex); entry.Add(new XElement("failure", ex.ToString())); results.Add(new { name, passed = false, error = ex.ToString() }); }
    entry.Add(new XAttribute("time", start.Elapsed.TotalSeconds)); suite.Add(entry);
}
suite.Add(new XAttribute("tests", tests.Count), new XAttribute("failures", failures));
Directory.CreateDirectory("TestResults"); File.WriteAllText("TestResults/core-results.json", JsonSerializer.Serialize(new { tests = tests.Count, failures, results }, new JsonSerializerOptions { WriteIndented = true })); new XDocument(suite).Save("TestResults/core-results.xml");
Console.WriteLine($"RESULT {tests.Count - failures}/{tests.Count} passed");
return failures == 0 ? 0 : 1;

sealed class TestClock : TimeProvider
{
    private DateTimeOffset _now = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);
    public override DateTimeOffset GetUtcNow() => _now;
    public void Advance(double seconds) => _now = _now.AddSeconds(seconds);
}
